function x(n){const t=new Date(n);return`${t.getFullYear()}-${String(t.getMonth()+1).padStart(2,"0")}-${String(t.getDate()).padStart(2,"0")} ${String(t.getHours()).padStart(2,"0")}:${String(t.getMinutes()).padStart(2,"0")}`}function $(n){const t=new Date(n);return`${t.getMonth()+1}月${t.getDate()}日`}function h(n){const t=new Date(n).getTime(),e=Date.now(),r=(t-e)/36e5;if(r<0){const s=Math.floor(-r/24);return{text:s>0?`已逾期 ${s} 天`:`已逾期 ${Math.floor(-r)} 小时`,cls:"text-red-600"}}if(r<24)return{text:`剩 ${Math.floor(r)} 小时`,cls:"text-red-600"};const o=Math.floor(r/24);return o<=3?{text:`剩 ${o} 天`,cls:"text-amber-600"}:o<=14?{text:`剩 ${o} 天`,cls:"text-slate-500"}:{text:`剩 ${o} 天`,cls:"text-slate-400"}}const l=6e4,f=60*l,a=24*f;function M(n,t=Date.now()){const e=new Date(n).getTime()-t,r=Math.abs(e),o=e<0||e<a?"text-red-600":e<=3*a?"text-amber-600":e<=14*a?"text-slate-600":"text-slate-400";if(e<0){const i=Math.floor(r/a),u=Math.floor(r%a/f);return i>0?{text:`已逾期 ${i} 天 ${u} 小时`,cls:o,overdue:!0}:u>0?{text:`已逾期 ${u} 小时`,cls:o,overdue:!0}:{text:`已逾期 ${Math.max(Math.floor(r/l),1)} 分钟`,cls:o,overdue:!0}}const s=Math.floor(e/a),c=Math.floor(e%a/f),d=Math.floor(e%f/l);return s>0?{text:`剩 ${s} 天 ${c} 小时`,cls:o,overdue:!1}:c>0?{text:`剩 ${c} 小时 ${d} 分`,cls:o,overdue:!1}:{text:`剩 ${Math.max(d,1)} 分钟`,cls:o,overdue:!1}}function g(n){const t=["#6366f1","#0ea5e9","#10b981","#f59e0b","#ef4444","#8b5cf6","#ec4899","#14b8a6"];let e=0;for(let r=0;r<n.length;r++)e=e*31+n.charCodeAt(r)>>>0;return t[e%t.length]}export{g as a,$ as b,M as c,h as d,x as f};
